const ids = ["G01","G02","G03","G04","G05","G06"];
const res = await Promise.all(ids.map(id => tools.origin_packet({case_id: id})));
const out:any = {cases:[]};
for (let i=0;i<ids.length;i++){
  const c = res[i].cases[0]; const e=c.evidence;
  const src: Record<string,string> = {};
  const allSources = new Set<string>();
  for (const m of e.material_index){ src[m.id]=m.source_id; allSources.add(m.source_id); }
  const parents: Record<string,string[]> = {};
  for (const l of e.links){
    if (l.relation === "derivation"){
      (parents[l.child] ||= []).push(l.parent);
    }
  }
  const memo: Record<string,Set<string>> = {};
  const calc = (id:string, stack:Set<string>):Set<string> => {
    if (memo[id]) return new Set(memo[id]);
    const ps = parents[id] || [];
    if (ps.length===0 || stack.has(id)) return new Set([src[id]]);
    stack.add(id);
    const s = new Set<string>();
    for (const p of ps) for (const o of calc(p, stack)) s.add(o);
    stack.delete(id);
    memo[id]=new Set(s);
    return s;
  };
  const queries = c.query_ids.map((q:string)=>({material_id:q, origins:[...calc(q,new Set())].sort()}));
  // check unknown refs
  const unknown = [...new Set(e.links.flatMap((l:any)=>[l.child,l.parent]))].filter((x:any)=>!src[x]);
  out.cases.push({id:c.id, recorded_origin_count:allSources.size, independence:"unknown", queries, _unknown:unknown, _rel:(()=>{const r:any={};for(const l of e.links)r[l.relation]=(r[l.relation]||0)+1;return r;})()});
}
