const ids = ["G01","G02","G03","G04","G05","G06"];
const res = await Promise.all(ids.map(id => tools.origin_packet({case_id: id})));
for (let i=0;i<ids.length;i++){
  const c=res[i].cases[0]; const e=c.evidence;
  const parents: Record<string,string[]> = {};
  for (const l of e.links) if (l.relation==="derivation") (parents[l.child] ||= []).push(l.parent);
  // cycle detection
  const color: Record<string,number> = {}; let cycles:string[]=[];
  const dfs=(u:string,path:string[])=>{
    color[u]=1;
    for(const p of (parents[u]||[])){
      if(color[p]===1) cycles.push([...path,u,p].join("->"));
      else if(!color[p]) dfs(p,[...path,u]);
    }
    color[u]=2;
  };
  for(const m of e.material_index) if(!color[m.id]) dfs(m.id,[]);
  const src:any={}; for(const m of e.material_index) src[m.id]=m.source_id;
  // leaf origins per query
  console.log("==",ids[i],"cycles:",cycles.length?cycles:"none");
  for(const q of c.query_ids){
    const leaves=new Set<string>(); const seen=new Set<string>();
    const rec=(id:string)=>{ if(seen.has(id))return; seen.add(id); const ps=parents[id]||[]; if(!ps.length){leaves.add(id);return;} for(const p of ps)rec(p); };
    rec(q);
    console.log(" ",q,"leaves:",[...leaves].map(x=>x+"("+src[x]+")").join(","));
  }
  if(ids[i]==="G04"){
    console.log("  citation links:",JSON.stringify(e.links.filter((l:any)=>l.relation!=="derivation")));
  }
}
